local FiddleMaker = {}
local PRODUCTS = {
    peasant_fiddle = { name = "Kmečka gosli", woodCost = 2, gutCost = 2, time = 2, cost = 30, soundQuality = 7, prestige = 1, description = "Preprosta kmečka gosli." },
    vielle = { name = "Vijela", woodCost = 3, gutCost = 4, time = 4, cost = 95, soundQuality = 11, prestige = 3, description = "Vijela z 5 strunami za potujoče pevce." },
    three_string_fiddle = { name = "Tristrunska gosli", woodCost = 3, gutCost = 3, time = 5, cost = 200, soundQuality = 14, prestige = 5, happiness = 1, description = "Tristrunska gosli za dvorne pevce." },
    rebec = { name = "Rebec", woodCost = 3, gutCost = 3, brassCost = 1, time = 7, cost = 440, soundQuality = 18, prestige = 9, happiness = 2, description = "Rebec v obliki ladje z medeninastim okovjem." },
    silver_fiddle = { name = "Srebrna gosli", woodCost = 4, silverCost = 1, gutCost = 4, time = 10, cost = 900, soundQuality = 24, prestige = 16, happiness = 4, description = "Srebrna gosli za plemiške dvorane." },
    royal_court_fiddle = { name = "Kraljevska dvorna gosli", woodCost = 5, goldCost = 2, silverCost = 1, gutCost = 5, pearlCost = 1, time = 14, cost = 2100, soundQuality = 36, prestige = 48, happiness = 10, description = "Velika kraljevska dvorna gosli z zlatim in bisernim okovjem za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Goslarska delavnica", cost = { gold = 260, wood = 130 }, upkeep = 6, qualityBonus = 5 },
    stringing_room = { name = "Strunarska soba", cost = { gold = 800, wood = 220, stone = 200, gut = 8 }, upkeep = 20, qualityBonus = 18 },
    bow_room = { name = "Lokarska soba", cost = { gold = 1700, wood = 280, stone = 350, silver = 25, wood2 = 8 }, upkeep = 40, qualityBonus = 30 },
    royal_fiddle_atelier = { name = "Kraljevski atelje gosli", cost = { gold = 6500, wood = 500, stone = 700, gold = 50, silver = 30 }, upkeep = 120, qualityBonus = 55, prestigeBonus = 30 },
}
FiddleMaker.woodStock = 16; FiddleMaker.gutStock = 12; FiddleMaker.brassStock = 8; FiddleMaker.silverStock = 6; FiddleMaker.goldStock = 6; FiddleMaker.pearlStock = 4
FiddleMaker.productStock = {}; FiddleMaker.buildings = {}; FiddleMaker.maker = nil; FiddleMaker.activeMaking = {}; FiddleMaker.totalProducts = 0; FiddleMaker.dayTimer = 0
function FiddleMaker.init() FiddleMaker.woodStock=16; FiddleMaker.gutStock=12; FiddleMaker.brassStock=8; FiddleMaker.silverStock=6; FiddleMaker.goldStock=6; FiddleMaker.pearlStock=4; FiddleMaker.productStock={}; FiddleMaker.buildings={}; FiddleMaker.maker=nil; FiddleMaker.activeMaking={}; FiddleMaker.totalProducts=0; FiddleMaker.dayTimer=0; print("[FiddleMaker] Royal Fiddle Maker System initialized (6 products, 4 buildings)") end
function FiddleMaker.hireMaker(n,s) s=s or math.random(50,90); local c=470+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FiddleMaker.maker={name=n or ("Goslar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Goslar najet: %s (spretnost: %d)",FiddleMaker.maker.name,s),"success") end; return true end
function FiddleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FiddleMaker.build(id) local ok,e=FiddleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FiddleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FiddleMaker.getQualityBonus() local b=0; for _,bd in ipairs(FiddleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FiddleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and FiddleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.gutCost and FiddleMaker.gutStock<(d.gutCost or 0) then return false,"Premalo črevesja" end; if d.brassCost and FiddleMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and FiddleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FiddleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.pearlCost and FiddleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FiddleMaker.buildings==0 then return false,"Potrebna delavnica" end; if not FiddleMaker.maker then return false,"Potreben goslar" end; return true end
function FiddleMaker.make(pt,qty) qty=qty or 1; local ok,e=FiddleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then FiddleMaker.woodStock=FiddleMaker.woodStock-d.woodCost*qty end; if d.gutCost then FiddleMaker.gutStock=FiddleMaker.gutStock-d.gutCost*qty end; if d.brassCost then FiddleMaker.brassStock=FiddleMaker.brassStock-d.brassCost*qty end; if d.silverCost then FiddleMaker.silverStock=FiddleMaker.silverStock-d.silverCost*qty end; if d.goldCost then FiddleMaker.goldStock=FiddleMaker.goldStock-d.goldCost*qty end; if d.pearlCost then FiddleMaker.pearlStock=FiddleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FiddleMaker.maker then t=math.max(1,t-math.floor(FiddleMaker.maker.skill/12)) end; table.insert(FiddleMaker.activeMaking,{id="fiddle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,soundQuality=d.soundQuality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FiddleMaker.completeMaking(m) local q=1.0+(FiddleMaker.getQualityBonus()/100); if FiddleMaker.maker then q=q+(FiddleMaker.maker.skill/180) end; q=math.min(2.0,q); FiddleMaker.productStock[m.productType]=(FiddleMaker.productStock[m.productType] or 0)+m.quantity; FiddleMaker.totalProducts=FiddleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FiddleMaker.maker then FiddleMaker.maker.itemsMade=FiddleMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then FiddleMaker.maker.skill=math.min(100,FiddleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gosli izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"fiddle.completed",{productName=m.productName,soundQuality=m.soundQuality}) end end
function FiddleMaker.update(dt) if not _G.state then return end; FiddleMaker.dayTimer=FiddleMaker.dayTimer+dt; if FiddleMaker.dayTimer>=30 then FiddleMaker.dayTimer=0; for i=#FiddleMaker.activeMaking,1,-1 do local m=FiddleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FiddleMaker.completeMaking(m); table.remove(FiddleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FiddleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FiddleMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FiddleMaker.getStats() return {woodStock=FiddleMaker.woodStock,gutStock=FiddleMaker.gutStock,brassStock=FiddleMaker.brassStock,silverStock=FiddleMaker.silverStock,goldStock=FiddleMaker.goldStock,pearlStock=FiddleMaker.pearlStock,productStock=FiddleMaker.productStock,numBuildings=#FiddleMaker.buildings,hasMaker=FiddleMaker.maker~=nil,makerName=FiddleMaker.maker and FiddleMaker.maker.name or "—",makerSkill=FiddleMaker.maker and FiddleMaker.maker.skill or 0,activeMaking=#FiddleMaker.activeMaking,totalProducts=FiddleMaker.totalProducts} end
return FiddleMaker
